#include <vector>
#include <cstddef>
#include <cmath>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    x.assign(N, 0.0);
    if (N == 0 || b.size() < N) return;

    // Build per-row sparse structure from COO in parallel (thread-safe via per-thread bins).
    int T = omp_get_max_threads();
    std::vector<std::vector<std::vector<std::pair<size_t, double>>>> threadRows(
        static_cast<size_t>(T), std::vector<std::vector<std::pair<size_t, double>>>(N));

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        auto& localRows = threadRows[static_cast<size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
            const COOElement& e = A[static_cast<size_t>(k)];
            if (e.row < N && e.column < N) {
                localRows[e.row].push_back({e.column, e.value});
            }
        }
    }

    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        size_t r = static_cast<size_t>(i);
        size_t total = 0;
        for (int t = 0; t < T; ++t) total += threadRows[static_cast<size_t>(t)][r].size();
        rows[r].reserve(total);
        for (int t = 0; t < T; ++t) {
            auto& src = threadRows[static_cast<size_t>(t)][r];
            rows[r].insert(rows[r].end(), src.begin(), src.end());
        }
    }

    // Jacobi iterative solver (robust for parallelism; each x_new[i] written by one thread).
    std::vector<double> x_old(N, 0.0), x_new(N, 0.0);
    const size_t maxIters = 5000;
    const double tol = 1e-10;

    for (size_t it = 0; it < maxIters; ++it) {
        double maxDiff = 0.0;

        #pragma omp parallel for schedule(static) reduction(max:maxDiff)
        for (std::ptrdiff_t ii = 0; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            size_t i = static_cast<size_t>(ii);
            double diag = 0.0;
            double sumOffDiag = 0.0;

            for (const auto& cv : rows[i]) {
                size_t j = cv.first;
                double v = cv.second;
                if (j == i) {
                    diag += v; // handle possible duplicate diagonal entries
                } else {
                    sumOffDiag += v * x_old[j];
                }
            }

            double xi = x_old[i];
            if (std::fabs(diag) > 1e-20) {
                xi = (b[i] - sumOffDiag) / diag;
            }
            x_new[i] = xi;

            double d = std::fabs(x_new[i] - x_old[i]);
            if (d > maxDiff) maxDiff = d;
        }

        x_old.swap(x_new);
        if (maxDiff < tol) break;
    }

    x = x_old;
}
